const icon = (name) => ({ dashboard:'<path d="M4 13h6V4H4v9Zm10 7h6V4h-6v16ZM4 20h6v-3H4v3Z"/>', students:'<circle cx="9" cy="8" r="3"/><path d="M3.5 20c.7-3.4 2.5-5 5.5-5s4.8 1.6 5.5 5M16 11h5M18.5 8.5v5"/>', followups:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>', log:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>' }[name]);
