function formatEventTime(value){ return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value)).replace(',', ' ·'); }
function followUpLabel(value){ const date=new Date(value); const now=new Date(); const dayStart=new Date(now.getFullYear(),now.getMonth(),now.getDate()); const dueStart=new Date(date.getFullYear(),date.getMonth(),date.getDate()); const diff=Math.round((dueStart-dayStart)/86400000); if(diff<=0)return 'Today'; if(diff===1)return 'Tomorrow'; if(diff===2)return 'In 2 days'; if(diff===3)return 'In 3 days'; return 'Next week'; }
function normalizeData(data){
  const followUpById=new Map(data.followUps.map(f=>[f.id,f]));
  const students=data.students.map(s=>{const guardian=s.guardians?.[0];return {...s,parent:guardian?.name??'Parent',relation:guardian?.relation??'Guardian',phone:guardian?.phone??'',guardianId:guardian?.id??null};});
  const rawEvents=data.events.map(e=>{const followUp=followUpById.get(e.follow_up_id);const plannedTopic=e.planned_topic||null;const discussedTopics=e.discussed_topics||((e.result==='Connected'&&e.topic)?[e.topic]:[]);return {id:e.id,studentId:e.student_id,guardianId:e.guardian_id,result:e.result,duration:formatCallDuration(e.duration_seconds),durationSeconds:e.duration_seconds,attemptNumber:e.attempt_number,topic:e.topic,plannedTopic,discussedTopics,note:e.teacher_note,callTime:e.call_time,time:formatEventTime(e.call_time),dateKey:new Date(e.call_time).toDateString()===new Date().toDateString()?'today':'older',followUp:followUp?followUpLabel(followUp.due_at):null,provider:e.provider,providerCallId:e.provider_call_id,providerStatus:e.provider_status,endedAt:e.ended_at};});
  const events=rawEvents.map(event=>({...event,attemptNumber:cycleAttemptNumber(rawEvents,event)}));
  const aiBriefs={};
  for(const brief of data.aiBriefs||[]){
    if(!aiBriefs[brief.student_id] || brief.version>aiBriefs[brief.student_id].version) aiBriefs[brief.student_id]={id:brief.id,version:brief.version,status:brief.status,brief:{key_topics:brief.key_topics||[],parent_concerns:brief.parent_concerns||[],recorded_resolutions:brief.recorded_resolutions||[],open_items:brief.open_items||[],suggested_next_step:brief.suggested_next_step||''},generatedAt:brief.generated_at};
  }
  return { students, events, followUps:data.followUps.map(f=>({...f,studentId:f.student_id,guardianId:f.guardian_id,dueAt:f.due_at,contactEventId:f.contact_event_id})), teacherNotes:(data.teacherNotes||[]).map(normalizeTeacherNote), aiContactBriefs:aiBriefs };
}
async function refreshData(){ const firstLoad=state.loading; state.error=null; if(firstLoad) render(); try { const data=await loadContactLoopData(); if(data.setupRequired){state.loading=false;state.error='setup';return render();} Object.assign(state,normalizeData(data),{loading:false,error:null}); render(); } catch(error){ console.error(error); state.loading=false; state.error=error.message||'Unable to load Supabase data.'; render(); } }
async function syncCallAndRefresh(eventId=null){ if(callPollingInFlight)return;callPollingInFlight=true;try{await getTelephonyProvider().syncCallStatus(eventId);await refreshData();}catch(error){console.warn('Call status sync is temporarily unavailable.',error);}finally{callPollingInFlight=false;} }
function beginCallPolling(eventId){ if(TELEPHONY_PROVIDER!=='twilio') return; clearInterval(callPollingTimer); window.setTimeout(()=>syncCallAndRefresh(eventId),1500); callPollingTimer=setInterval(()=>syncCallAndRefresh(eventId),3000); window.setTimeout(()=>{clearInterval(callPollingTimer);callPollingTimer=null;},300000); }
async function startRealCall(id,plannedTopic=null){ if(callStartInFlight)return;callStartInFlight=true;try { state.selectedStudentId=id; const provider=getTelephonyProvider(); const call=await provider.startCall(id,{plannedTopic}); state.screen='detail'; await refreshData(); beginCallPolling(call.eventId); } catch(error) { state.error=error.message||'Unable to start the call.'; render(); } finally { callStartInFlight=false; } }
function handleCallClick(id){ return openCallFlow(id); }

function statusClass(result){ return result.toLowerCase().replace(' ','-'); }
function renderNav(){ return navItems.map(([id,label])=>`<button class="${state.screen===id?'active':''}" data-nav="${id}"><svg viewBox="0 0 24 24">${icon(id)}</svg><span>${label}</span></button>`).join(''); }
function avatar(s, cls='avatar'){ return `<div class="${cls}">${s.initials}</div>`; }

function homeScreen(){ return `<div class="home-page"><header class="home-nav"><button class="home-brand" data-home><span class="brand-mark">C</span><span>Contact<span>Loop</span></span></button><div class="home-nav-links"><a href="#how-it-works">How it works</a><a href="#privacy">Privacy first</a></div></header><main class="hero"><div class="hero-copy"><p class="eyebrow">Built for special education teams</p><h1>Every contact,<br><em>automatically tracked.</em></h1><p class="hero-subhead">Automatically track parent calls, outcomes, and follow-ups for special education teams.</p><div class="hero-actions"><button class="button-primary hero-cta" data-action="demo">Try the demo <span>→</span></button><span class="hero-note">No setup. No call log digging.</span></div></div><div class="hero-visual"><div class="hero-orbit orbit-one"><span>CONTACT</span></div><div class="hero-orbit orbit-two"><span>FOLLOW-UP</span></div><div class="loop-spark spark-one"></div><div class="loop-spark spark-two"></div><div class="browser-window"><div class="browser-bar"><span class="browser-dots"><i></i><i></i><i></i></span><span class="browser-url">app.contactloop.co / dashboard</span><span>•••</span></div><div class="browser-body"><div class="browser-brand">Contact<span>Loop</span></div><div class="browser-greeting"><span>TUESDAY, AUG 25</span><strong>Good morning, Bella<span>.</span></strong></div><div class="browser-stats"><div><small>CALLS</small><b>4</b></div><div><small>CONNECTED</small><b>2</b></div><div><small>NO ANSWER</small><b>2</b></div></div><div class="browser-activity"><small>RECENT ACTIVITY</small><div>${avatar({initials:'EJ'},'mini-avatar')}<span><strong>Emma Johnson</strong><em>No answer · Attempt #3</em></span><b>Follow up</b></div><div>${avatar({initials:'LS'},'mini-avatar')}<span><strong>Lucas Smith</strong><em>Connected · 7m 43s</em></span><b class="done">Done</b></div></div></div></div><div class="hero-float"><span class="float-check">✓</span><div><strong>Call documented</strong><small>Emma Johnson · No Answer</small><small>Follow-up scheduled for tomorrow</small></div></div></div></main><section class="home-proof" id="how-it-works"><div><span class="proof-number">01</span><strong>Call from ContactLoop</strong><p>One tap starts the conversation with the right family.</p></div><div><span class="proof-number">02</span><strong>Outcome captured automatically</strong><p>Connected, no answer, busy, or failed — no manual log.</p></div><div><span class="proof-number">03</span><strong>Follow-ups stay visible</strong><p>Never lose track of who needs another contact attempt.</p></div></section><section class="privacy-strip" id="privacy"><span>PRIVATE BY DESIGN</span><p>No call recordings. No transcripts. Just the contact data your team needs.</p></section></div>`; }

function dashboard(){
  const filteredEvents=filterEventsByRange(state.events,state.dashboardRange);
  const insights=getDashboardInsights({events:state.events,students:state.students,followUps:state.followUps,range:state.dashboardRange});
  const recent=newestContactEventsFirst(filteredEvents.filter(e=>['Connected','No Answer','Busy','Failed'].includes(e.result))).slice(0,5);
  const customRangeInvalid=state.dashboardRange.preset==='custom'&&state.dashboardRange.from&&state.dashboardRange.to&&state.dashboardRange.from>state.dashboardRange.to;
  const followUpCount=insights.needsFollowUp.length;
  const followUpMessage=`${followUpCount} follow-up${followUpCount===1?'':'s'} need${followUpCount===1?'s':''} your attention today.`;
  const onboarding=state.students.length===0?'<div class="dashboard-onboarding"><div><p class="eyebrow">Start here</p><h2>Set up ContactLoop</h2><p>Import your student and guardian list to start tracking parent communication.</p></div><button class="button-primary" data-action="import-students">Import students <span>→</span></button></div>':'';
  const brief=insights.weekBrief;
  const topics=brief.topTopics.length?brief.topTopics.map(topic=>`<span class="topic-chip">${topic.label}<b>${topic.count}</b></span>`).join(''):'<span class="brief-muted">No topics captured yet.</span>';
  return `<div class="topbar"><div><p class="eyebrow">Tuesday, August 25, 2026</p><h1>Good morning, Bella<span style="color:var(--coral)">.</span></h1><p class="subhead">${followUpMessage}</p></div><div class="topbar-actions"><div class="dashboard-range"><label for="dashboard-range">View</label><select id="dashboard-range"><option value="today" ${state.dashboardRange.preset==='today'?'selected':''}>Today</option><option value="yesterday" ${state.dashboardRange.preset==='yesterday'?'selected':''}>Yesterday</option><option value="this-week" ${state.dashboardRange.preset==='this-week'?'selected':''}>This week</option><option value="this-month" ${state.dashboardRange.preset==='this-month'?'selected':''}>This month</option><option value="this-year" ${state.dashboardRange.preset==='this-year'?'selected':''}>This year</option><option value="custom" ${state.dashboardRange.preset==='custom'?'selected':''}>Custom</option></select><span class="range-label">${rangeLabel(state.dashboardRange)}</span>${state.dashboardRange.preset==='custom'?`<div class="custom-range"><label>From <input id="dashboard-from" type="date" value="${state.dashboardRange.from}"></label><label>To <input id="dashboard-to" type="date" value="${state.dashboardRange.to}"></label></div>${customRangeInvalid?'<small class="range-error">From must be before To.</small>':''}`:''}</div><button class="button-primary call-parent-top" data-action="call-parent">+ Call Parent</button><div class="profile">${avatar({initials:'B'})}<div><strong>Bella Rivera</strong><span>Special education · Room 204</span></div></div></div></div>
    ${onboarding}<div class="metric-grid">${[['Call Attempts',insights.metrics.callAttempts,'↗','coral'],['Connected',insights.metrics.connected,'✓','mint'],['Unsuccessful',insights.metrics.unsuccessful,'–','amber'],['Follow-ups Due',insights.metrics.followUpsDue,'!','blue']].map(x=>`<div class="metric"><div class="metric-top"><span>${x[0]}</span><span class="metric-icon ${x[3]}">${x[2]}</span></div><div class="metric-value">${x[1]}</div></div>`).join('')}</div>
    <div class="demo-guide"><div class="guide-kicker"><span class="guide-pulse"></span>Demo mode</div><div><h2>See the magic in one call.</h2><p>Try the core loop: make a call, choose an outcome, and watch the dashboard update itself.</p></div><button class="button-primary" data-action="try-emma">Call Emma’s mom <span>→</span></button></div>
    <div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Needs Follow-up</h2><span>${followUpCount} open item${followUpCount===1?'':'s'}</span></div>${insights.needsFollowUp.slice(0,5).map(item=>`<div class="attention-item"><span class="attention-dot"></span>${avatar(item.student,'mini-avatar')}<div><h3>${item.student.name}</h3><p>${item.label}</p></div><button class="attention-action" data-call="${item.student.id}">${item.actionLabel}</button></div>`).join('')||'<div class="empty-state">You’re all caught up.</div>'}</section>
    <section class="panel brief-panel"><div class="panel-head"><h2>This Week</h2><span>Contact brief</span></div><div class="brief-body"><div class="brief-stat"><span>Total call attempts</span><strong>${brief.totalAttempts}</strong></div><div class="brief-stat"><span>Successful contacts</span><strong>${brief.successfulContacts}</strong></div><div class="brief-stat"><span>Students needing follow-up</span><strong>${brief.studentsNeedingFollowUp}</strong></div><div class="brief-topics"><span class="brief-label">Top topics</span><div class="topic-list">${topics}</div></div></div></section>
    <section class="panel activity"><div class="panel-head"><h2>Recent Activity</h2><button class="button-secondary" style="width:auto;padding:7px 11px" data-nav="log">View all</button></div>${activityTable(recent)}</section></div>`;
}

function activityTable(events){ return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Parent</th><th>When</th><th>Result</th><th>Duration</th><th>Attempt</th></tr></thead><tbody>${events.map(e=>{const s=eventStudent(e);return `<tr><td><div class="student-cell">${avatar(s,'mini-avatar')}<span>${s.name}</span></div></td><td class="secondary">${s.relation}</td><td class="mono secondary">${e.time}</td><td><span class="status ${statusClass(e.result)}">${e.result}</span></td><td class="mono">${e.duration||'—'}</td><td class="mono">#${e.attemptNumber}</td></tr>`}).join('')}</tbody></table></div>`; }
function contactLogTable(events){ return `<div class="table-wrap"><table class="contact-log-table"><thead><tr><th>Student</th><th>Parent</th><th>When</th><th>Outcome</th><th>Duration</th><th>Planned topic</th><th>Discussed topics</th><th>Attempt</th></tr></thead><tbody>${events.map(e=>{const s=eventStudent(e);return `<tr class="log-row" tabindex="0" data-log-event="${e.id}"><td><div class="student-cell">${avatar(s,'mini-avatar')}<span>${s.name}</span></div></td><td class="secondary">${s.relation}</td><td class="mono secondary">${e.time}</td><td><span class="status ${statusClass(e.result)}">${e.result}</span></td><td class="mono">${e.duration||'—'}</td><td>${escapeHtml(e.plannedTopic||'—')}</td><td>${escapeHtml(e.result==='Connected'?discussedTopicsForEvent(e).join(', '):'—')}</td><td class="mono">#${e.attemptNumber}</td></tr>`}).join('')||'<tr><td colspan="8" class="log-empty">No contact records match these filters.</td></tr>'}</tbody></table></div>`; }
function legacyStudentsScreen(){ const matches=filterStudents(state.students,state.studentSearch); return `<div class="screen-title"><div><p class="eyebrow">Your caseload</p><h1>Students</h1><p class="subhead">${state.students.length} students · click a card to see contact history.</p></div><button data-action="new-student">+ Add student</button></div><div class="student-page-search"><span>⌕</span><input id="student-page-search" type="search" value="${escapeHtml(state.studentSearch)}" placeholder="Search students, parents, or phone numbers…" aria-label="Search students, parents, or phone numbers"></div><div class="student-grid">${matches.map(s=>{const latest=newestContactEventsFirst(state.events.filter(e=>e.studentId===s.id))[0];return `<article class="student-card"><div class="student-card-top">${avatar(s)}<span class="status ${latest?.result==='Connected'?'connected':'no-answer'}">${latest?.result==='Connected'?'On track':'Needs follow-up'}</span></div><h2>${s.name}</h2><p>${s.relation} · ${s.parent}<br>${s.phone}</p><div class="card-meta"><strong>${state.events.filter(e=>e.studentId===s.id).length}</strong> contact events · Last ${latest?.time||'not contacted'}</div><button class="button-secondary" data-student="${s.id}">View contact history</button></article>`}).join('')||'<div class="panel empty-state student-search-empty">No students match your search.</div>'}</div>`; }
function studentsScreen(){
  const matches=filterStudents(state.students,state.studentSearch);
  if(!state.students.length)return `<div class="screen-title"><div><p class="eyebrow">Your caseload</p><h1>Students</h1><p class="subhead">Your students and their guardian contacts.</p></div><button class="button-secondary import-header-button" data-action="import-students">Import Students</button></div><section class="students-empty panel"><div class="empty-orb">+</div><h2>Add your students to get started</h2><p>Import a spreadsheet or add students manually.</p><div class="empty-actions"><button class="button-primary" data-action="import-students">Import CSV / Excel</button><button class="button-secondary" data-action="new-student">Add student manually</button></div></section>`;
  return `<div class="screen-title"><div><p class="eyebrow">Your caseload</p><h1>Students</h1><p class="subhead">${state.students.length} students · click a card to see contact history.</p></div><div class="student-header-actions"><button class="button-secondary" data-action="new-student">+ Add Student</button><button class="button-primary" data-action="import-students">Import Students</button></div></div><div class="student-page-search"><span>⌕</span><input id="student-page-search" type="search" value="${escapeHtml(state.studentSearch)}" placeholder="Search students, parents, or phone numbers…" aria-label="Search students, parents, or phone numbers"></div><div class="student-grid">${matches.map(s=>{const latest=newestContactEventsFirst(state.events.filter(e=>e.studentId===s.id))[0];return `<article class="student-card"><div class="student-card-top">${avatar(s)}<span class="status ${latest?.result==='Connected'?'connected':'no-answer'}">${latest?.result==='Connected'?'On track':'Needs follow-up'}</span></div><h2>${s.name}</h2><p>${s.relation} · ${s.parent}<br>${s.phone}</p><div class="card-meta"><strong>${state.events.filter(e=>e.studentId===s.id).length}</strong> contact events · Last ${latest?.time||'not contacted'}</div><button class="button-secondary" data-student="${s.id}">View contact history</button></article>`}).join('')||'<div class="panel empty-state student-search-empty">No students match your search.</div>'}</div>`;
}
function contactSummaryRange(events){const times=events.map(event=>new Date(event.callTime).getTime()).filter(Number.isFinite);const from=times.length?new Date(Math.min(...times)).toISOString():new Date(Date.now()-30*86400000).toISOString();const to=new Date(Date.now()+86400000).toISOString();return {from,to};}
function aiSummaryFields(){return [['key_topics','Key topics'],['parent_concerns','Parent concerns'],['recorded_resolutions','Recorded resolutions'],['open_items','Open items']];}
function renderAiSummaryEdit(id,result){const editor=result.editor||createEditableBrief(result.brief);result.editor=editor;const fields=aiSummaryFields().map(([field,label])=>`<div class="ai-summary-edit-section"><label>${label}</label><div class="ai-edit-list">${editor.brief[field].map((item,index)=>`<div class="ai-edit-row"><input data-ai-item="${field}" data-ai-index="${index}" value="${escapeHtml(item)}"><button type="button" aria-label="Delete ${label} item" data-ai-delete="${field}:${index}">Delete</button></div>`).join('')}</div><button type="button" class="ai-add-item" data-ai-add="${field}">+ Add ${label.toLowerCase().replace(/s$/,'')}</button></div>`).join('');return `<div class="ai-summary-edit-form">${fields}<div class="ai-summary-edit-section"><label for="ai-next-step">Suggested next step</label><textarea id="ai-next-step" data-ai-next-step>${escapeHtml(editor.brief.suggested_next_step)}</textarea></div><div class="ai-summary-actions"><button class="button-secondary" data-ai-cancel="${id}">Cancel</button><button class="button-primary" data-ai-save="${id}">Save changes</button></div></div>`;}
function renderAiContactSummary(id){const s=student(id);const events=state.events.filter(event=>event.studentId===id);const stats=buildContactSummaryStats({studentId:id,events,followUps:state.followUps});const result=state.aiContactBriefs[id];const lists=result?.brief?[['Key topics',result.brief.key_topics],['Parent concerns',result.brief.parent_concerns],['Recorded resolutions',result.brief.recorded_resolutions],['Open items',result.brief.open_items]].map(([label,items])=>`<div class="ai-summary-section"><span>${label}</span>${items?.length?`<ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<p>No confirmed information recorded.</p>'}</div>`).join(''):'';const approveAction=result?.status==='approved'?'<span class="ai-summary-approved">✓ Teacher Approved</span>':`<button class="button-primary" data-ai-approve="${id}">Approve summary</button>`;const content=result?.editing?renderAiSummaryEdit(id,result):result?.brief?`<div class="ai-review-badge">${result.status==='approved'?'Teacher Approved':'Needs teacher review'}</div>${lists}<div class="ai-next-step"><span>Suggested next step</span><p>${escapeHtml(result.brief.suggested_next_step||'No suggested next step recorded.')}</p></div><div class="ai-summary-actions"><button class="button-secondary" data-ai-edit="${id}">Edit</button>${approveAction}<div class="ai-menu-wrap"><button class="button-secondary ai-menu-button" aria-label="More summary actions" data-ai-menu-toggle="${id}">•••</button><div class="ai-menu" data-ai-menu="${id}"><button data-ai-regenerate="${id}">Regenerate summary</button><button data-ai-remove="${id}">Remove summary</button></div></div></div>`:result?.loading?'':`<p class="ai-summary-empty">Summarize the recorded topics, teacher notes, and open follow-ups for ${escapeHtml(s?.name||'this student')}.</p><button class="button-primary ai-generate-button" data-ai-generate="${id}" ${aiContactBriefEnabled?'':'disabled'}>${aiContactBriefEnabled?'Generate summary':'AI provider not configured'}</button>`;return `<aside class="ai-summary-card"><div class="ai-summary-header"><div><p class="eyebrow">AI-assisted, teacher-controlled</p><h2>AI Contact Summary</h2></div><span class="ai-summary-spark">✦</span></div><div class="ai-summary-stats"><div><strong>${stats.attempts}</strong><span>Attempts</span></div><div><strong>${stats.connected}</strong><span>Connected</span></div><div><strong>${stats.unsuccessful}</strong><span>Unsuccessful</span></div><div><strong>${stats.openFollowUps}</strong><span>Open follow-up</span></div></div>${result?.loading?'<p class="ai-summary-empty">Reading confirmed contact context…</p>':''}${result?.error?`<div class="ai-summary-error">${escapeHtml(result.error)}</div>`:''}${content}</aside>`;}
async function generateAiContactSummary(id){if(!aiContactBriefEnabled)return;const events=state.events.filter(event=>event.studentId===id);const range=contactSummaryRange(events);const previous=state.aiContactBriefs[id];state.aiContactBriefs[id]={loading:true};render();try{const result=await contactBriefProvider.generate({studentId:id,dateFrom:range.from,dateTo:range.to,includeNotes:true});const version=(previous?.version||0)+1;const saved=await saveAiContactBrief({studentId:id,dateFrom:range.from,dateTo:range.to,version,status:'draft',brief:result.brief});if(previous?.id)await supersedeAiContactBrief(previous.id);state.aiContactBriefs[id]={...result,...saved,loading:false,status:'draft',version:saved.version};}catch(error){state.aiContactBriefs[id]={...previous,error:error.message||'Unable to generate AI summary.',loading:false};}render();}
function beginAiSummaryEdit(id){const result=state.aiContactBriefs[id];if(!result?.brief)return;result.editor=createEditableBrief(result.brief);result.editing=true;render();}
function cancelAiSummaryEdit(id){const result=state.aiContactBriefs[id];if(!result)return;result.editor=cancelBriefEdits(result.editor||createEditableBrief(result.brief));result.editing=false;render();}
async function saveAiSummaryEdits(id){const result=state.aiContactBriefs[id];if(!result?.editor)return;try{const saved=result.id?await updateAiContactBrief(result.id,{brief:result.editor.brief,status:'draft'}):await saveAiContactBrief({studentId:id,dateFrom:contactSummaryRange(state.events.filter(event=>event.studentId===id)).from,dateTo:contactSummaryRange(state.events.filter(event=>event.studentId===id)).to,version:result.version||1,status:'draft',brief:result.editor.brief});state.aiContactBriefs[id]={...result,brief:result.editor.brief,id:saved.id,version:saved.version,status:'draft',editing:false,editor:null,error:null};render();}catch(error){result.error=error.message||'Unable to save summary changes.';render();}}
async function approveAiSummary(id){const result=state.aiContactBriefs[id];if(!result)return;try{if(result.id)await approveAiContactBrief(result.id);result.status='approved';result.approved=true;render();}catch(error){result.error=error.message||'Unable to approve summary.';render();}}
async function removeAiSummary(id){const result=state.aiContactBriefs[id];try{if(result?.id)await removeAiContactBrief(result.id);delete state.aiContactBriefs[id];render();}catch(error){result.error=error.message||'Unable to remove summary.';render();}}
function openVoiceNote(id){state.selectedStudentId=id;state.voiceNote=createVoiceNoteState();state.modal={step:'voice'};renderModal();startVoiceRecording();}
function closeVoiceNote(){if(state.voiceNote.recorder?.state==='recording')state.voiceNote.recorder.stop();if(state.voiceNote.timer)clearInterval(state.voiceNote.timer);state.modal=null;state.voiceNote=createVoiceNoteState();document.querySelector('#modal-root').innerHTML='';}
function renderVoiceModal(){const voice=state.voiceNote;const busy=['uploading','transcribing','saving'].includes(voice.status);let body='';if(voice.status==='idle')body='<p class="voice-help">Record a short note to add context to this student’s communication history.</p><button class="button-primary" data-voice-start>Start recording</button>';if(voice.status==='recording')body=`<div class="voice-timer">${String(Math.floor(voice.elapsedSeconds/60)).padStart(2,'0')}:${String(voice.elapsedSeconds%60).padStart(2,'0')}</div><button class="button-primary" data-voice-stop>Stop</button>`;if(voice.status==='uploading')body='<p class="voice-progress">Uploading…</p>';if(voice.status==='transcribing')body='<p class="voice-progress">Transcribing…</p>';if(voice.status==='review')body=`<label class="modal-label" for="voice-transcript">Voice transcript</label><textarea id="voice-transcript" class="voice-transcript">${escapeHtml(voice.transcript)}</textarea><button class="button-primary" data-voice-save>Save note</button>`;if(voice.status==='error')body=`<div class="ai-summary-error">${escapeHtml(voice.error)}</div><button class="button-secondary" data-voice-retry>Try again</button>`;return `<div class="modal-backdrop"><div class="modal voice-modal"><div class="modal-header"><div><p class="eyebrow">Teacher context</p><h2>Add context by voice</h2><p>Record a short note to add context to this student's communication history.</p></div><button class="close" data-voice-cancel>×</button></div><div class="voice-body">${body}</div>${!busy&&voice.status!=='review'?'<div class="modal-footer"><button class="button-cancel" data-voice-cancel>Cancel</button></div>':''}</div></div>`;}
async function pollVoiceTranscript(studentId,jobId){state.voiceNote.status='transcribing';renderModal();try{for(let attempt=0;attempt<30;attempt+=1){const result=await getVoiceTranscriptStatus({studentId,jobId,objectKey:state.voiceNote.objectKey});if(result.status==='completed'){const transcript=(result.transcript||'').trim();if(!transcript)throw new Error('No speech detected. Please record a little longer and speak clearly.');state.voiceNote.status='review';state.voiceNote.transcript=transcript;return renderModal();}if(result.status==='failed')throw new Error('Transcription failed. Please try recording again.');await new Promise(resolve=>setTimeout(resolve,2000));}throw new Error('Transcription timed out. Please try again.');}catch(error){state.voiceNote=voiceNoteError(error.message||'Transcription failed');renderModal();}}
async function stopVoiceRecording(){const voice=state.voiceNote;const recorder=voice.recorder;if(!recorder)return;recorder.stop();}
function startVoiceRecording(){const voice=state.voiceNote;if(!['idle','error'].includes(voice.status))return;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){state.voiceNote=voiceNoteError('Voice recording is not supported in this browser.');return renderModal();}navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{const chunks=[];const recorder=new MediaRecorder(stream);state.voiceNote={...state.voiceNote,status:'recording',recorder,elapsedSeconds:0,chunks,error:null};recorder.ondataavailable=event=>chunks.push(event.data);recorder.onstop=async()=>{stream.getTracks().forEach(track=>track.stop());if(state.voiceNote.timer)clearInterval(state.voiceNote.timer);state.voiceNote={...state.voiceNote,status:'uploading',recorder:null,timer:null};renderModal();try{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});const upload=await createVoiceUpload({studentId:state.selectedStudentId,contentType:blob.type});const uploaded=await fetch(upload.uploadUrl,{method:'PUT',headers:{'Content-Type':blob.type},body:blob});if(!uploaded.ok)throw new Error(`Audio upload failed (${uploaded.status}).`);const job=await startVoiceTranscription({studentId:state.selectedStudentId,objectKey:upload.objectKey});if(!job?.jobId)throw new Error('Transcription did not return a job id.');state.voiceNote.objectKey=upload.objectKey;await pollVoiceTranscript(state.selectedStudentId,job.jobId);}catch(error){state.voiceNote=voiceNoteError(edgeFunctionError(error,'Voice note service'));renderModal();}};recorder.start();state.voiceNote.timer=setInterval(()=>{state.voiceNote.elapsedSeconds+=1;renderModal();},1000);renderModal();}).catch(error=>{state.voiceNote=voiceNoteError(error.message||'Microphone permission was denied.');renderModal();});}
function renderContextSavedNotice(studentId){const card=document.querySelector('.ai-summary-card');if(!card)return;const actions=card.querySelector('.ai-summary-actions');const generate=card.querySelector('[data-ai-generate]');const target=actions||generate;if(!target)return;const notice=document.createElement('div');notice.className='ai-context-saved';notice.innerHTML='<strong>New context saved.</strong><span>Update the AI Contact Summary with this note?</span><button class="button-secondary" data-ai-update-summary>Update AI Summary</button>';target.parentNode.insertBefore(notice,target);notice.querySelector('[data-ai-update-summary]').onclick=()=>{const result=state.aiContactBriefs[studentId];if(result)result.contextSaved=false;notice.remove();generateAiContactSummary(studentId);};}
async function saveVoiceNote(){const transcript=document.querySelector('#voice-transcript')?.value?.trim();if(!transcript||!canSaveVoiceNote({...state.voiceNote,transcript}))return;const studentId=state.selectedStudentId;state.voiceNote.transcript=transcript;state.voiceNote.status='saving';renderModal();try{await createTeacherNote({studentId,content:transcript,source:'voice'});closeVoiceNote();await refreshData();const brief=state.aiContactBriefs[studentId];state.aiContactBriefs[studentId]={...brief,contextSaved:true};render();renderContextSavedNotice(studentId);}catch(error){state.voiceNote=voiceNoteError(error.message||'Unable to save note.');renderModal();}}
function openTeacherNote(id){state.selectedStudentId=id;state.modal={step:'teacher-note',content:'',error:null,saving:false};renderModal();}
function closeTeacherNote(){state.modal=null;document.querySelector('#modal-root').innerHTML='';}
function renderTeacherNoteModal(){const m=state.modal;const s=student(state.selectedStudentId);return `<div class="modal-backdrop"><div class="modal teacher-note-modal"><div class="modal-header"><div><p class="eyebrow">Teacher context</p><h2>Add a teacher note</h2><p>Write a short, confirmed note about ${escapeHtml(s?.name||'this student')}.</p></div><button class="close" data-teacher-note-cancel>×</button></div>${m.error?`<div class="ai-summary-error">${escapeHtml(m.error)}</div>`:''}<label class="modal-label" for="teacher-note-input">Note · teacher confirmed</label><textarea id="teacher-note-input" class="teacher-note-input" placeholder="e.g. Parent asked about homework and confirmed Friday’s meeting.">${escapeHtml(m.content||'')}</textarea><div class="modal-footer"><button class="button-cancel" data-teacher-note-cancel>Cancel</button><button class="button-primary" data-teacher-note-save ${m.saving||!m.content?.trim()?'disabled':''}>Save note</button></div></div></div>`;}
function bindTeacherNoteModalEvents(){document.querySelectorAll('[data-teacher-note-cancel]').forEach(button=>button.onclick=closeTeacherNote);const input=document.querySelector('#teacher-note-input');if(input)input.oninput=()=>{state.modal.content=input.value;const save=document.querySelector('[data-teacher-note-save]');if(save)save.disabled=!input.value.trim()||state.modal.saving;};document.querySelector('[data-teacher-note-save]')?.addEventListener('click',saveTypedTeacherNote);}
async function saveTypedTeacherNote(){const m=state.modal;const content=m?.content?.trim();if(!content||m.saving)return;const studentId=state.selectedStudentId;m.saving=true;m.error=null;renderModal();try{await createTeacherNote({studentId,content,source:'typed'});closeTeacherNote();await refreshData();const brief=state.aiContactBriefs[studentId];state.aiContactBriefs[studentId]={...brief,contextSaved:true};render();renderContextSavedNotice(studentId);}catch(error){state.modal={...m,saving:false,error:error.message||'Unable to save note.'};renderModal();}}
function renderTeacherNotes(id){const notes=notesForStudent(state.teacherNotes,id);return `<section class="teacher-notes-card"><div class="teacher-notes-head"><div><p class="eyebrow">Your confirmed context</p><h2>Teacher Notes</h2><p>Notes you add here stay separate from the AI summary until you choose to update it.</p></div><div class="teacher-notes-actions"><button class="button-secondary" data-add-teacher-note="${id}">+ Add note</button><button class="button-secondary" data-add-teacher-voice="${id}">🎤 Voice</button></div></div>${notes.length?`<div class="teacher-notes-list">${notes.map(note=>`<article class="teacher-note"><div><strong>${teacherNoteSourceLabel(note.source)}</strong><span>${formatEventTime(note.createdAt)}</span></div><p>${escapeHtml(note.content)}</p></article>`).join('')}</div>`:'<div class="teacher-notes-empty">No teacher notes yet. Add typed or voice context after a call.</div>'}</section>`;}
function detailScreen(id){const s=student(id);const events=newestContactEventsFirst(state.events.filter(e=>e.studentId===id));const open=events.find(e=>e.followUp);return `<button class="back" data-nav="students">← Back to students</button><div class="detail-head">${avatar(s)}<div><h1>${s.name}</h1><p>${s.relation} · ${s.parent} · ${s.phone}</p></div><div class="detail-actions"><button class="button-primary" data-call="${s.id}">Call ${s.relation}</button></div></div><div class="detail-layout"><div><div class="history"><div class="panel-head" style="padding-left:0;padding-right:0;border-bottom:0"><h2>Contact history</h2><span>${events.length} events</span></div>${events.map(e=>`<div class="history-item"><div class="history-time">${e.time.replace(' · ','<br>')}</div><div class="history-marker"></div><div class="history-card"><div class="history-card-top"><h3>Phone call · <span class="status ${statusClass(e.result)}">${e.result}</span></h3><span class="mono secondary">Attempt #${e.attemptNumber}</span></div>${e.duration?`<p><strong>${e.duration}</strong> conversation</p>`:''}${e.topic?`<p>Topic: <strong>${e.topic}</strong></p>`:''}${e.note?`<p class="history-note">“${escapeHtml(e.note)}”</p>`:''}</div></div>`).join('')}</div>${open?`<div class="followup-card"><h3>Follow-up scheduled · ${open.followUp}</h3><p>This student will stay on your attention list until the next contact is logged.</p></div>`:''}${renderTeacherNotes(id)}</div>${renderAiContactSummary(id)}</div>`; }
function followupsScreen(){
  const items=buildFollowUpItems({followUps:state.followUps,events:state.events,students:state.students});
  const groups=['TODAY','TOMORROW','UPCOMING'];
  const grouped=groups.map(group=>{const groupItems=items.filter(item=>item.group===group);if(!groupItems.length)return '';return `<section class="followup-group"><div class="followup-group-label">${group}<span>${groupItems.length}</span></div><div class="followup-list">${groupItems.map(item=>`<div class="followup-row">${avatar(item.student)}<div class="followup-main"><h3>${item.student.name} · ${item.student.relation}</h3><p>${item.summary}</p><small>Last attempt: ${item.lastContact}</small></div><div class="followup-due"><strong>${item.nextFollowUp}</strong></div><button class="button-primary followup-call" data-call="${item.student.id}">Call</button><div class="followup-menu-wrap"><button class="followup-menu-button" aria-label="More actions for ${item.student.name}" data-followup-menu-toggle="${item.id}">•••</button><div class="followup-menu" data-followup-menu="${item.id}"><button data-followup-reschedule="${item.id}">Reschedule</button><button data-followup-done="${item.id}">Mark done</button><button data-followup-history="${item.student.id}">View contact history</button></div></div></div>`).join('')}</div></section>`;}).join('');
  return `<div class="screen-title"><div><p class="eyebrow">Keep the loop closed</p><h1>Follow-ups</h1><p class="subhead">${items.length} open follow-up${items.length===1?'':'s'} · Your next contacts, in priority order.</p></div></div>${grouped||'<div class="panel empty-state">No open follow-ups right now. You’re all caught up.</div>'}`;
}
function logScreen(){const f=state.logFilters;const filtered=filterContactLogEvents(state.events,f,state.students);const customInvalid=f.range.preset==='custom'&&f.range.from&&f.range.to&&f.range.from>f.range.to;return `<div class="screen-title"><div><p class="eyebrow">Every touch, accounted for</p><h1>Contact Log</h1><p class="subhead">A complete record of parent communication.</p></div><div class="log-actions"><button class="button-secondary brief-entry" data-action="meeting-brief">Generate Meeting Brief</button><button data-action="export-log">Export Contact Records</button></div></div><div class="log-filters"><label class="log-search"><span>⌕</span><input id="log-search" type="search" value="${escapeHtml(f.search)}" placeholder="Search contacts…" aria-label="Search contacts"></label><label><span>Date range</span><select id="log-range"><option value="today" ${f.range.preset==='today'?'selected':''}>Today</option><option value="this-week" ${f.range.preset==='this-week'?'selected':''}>This Week</option><option value="this-month" ${f.range.preset==='this-month'?'selected':''}>This Month</option><option value="this-year" ${f.range.preset==='this-year'?'selected':''}>This Year</option><option value="custom" ${f.range.preset==='custom'?'selected':''}>Custom</option></select></label><label><span>Outcome</span><select id="log-outcome"><option value="all">All outcomes</option>${['Connected','No Answer','Busy','Failed'].map(value=>`<option value="${value}" ${f.outcome===value?'selected':''}>${value}</option>`).join('')}</select></label><label><span>Student</span><select id="log-student"><option value="all">All students</option>${state.students.map(s=>`<option value="${s.id}" ${f.studentId===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label>${f.range.preset==='custom'?`<div class="log-custom-range"><label>From <input id="log-from" type="date" value="${f.range.from}"></label><label>To <input id="log-to" type="date" value="${f.range.to}"></label></div>${customInvalid?'<small class="range-error">From must be before To.</small>':''}`:''}</div><section class="panel activity"><div class="panel-head"><h2>Contact records</h2><span>${filtered.length} record${filtered.length===1?'':'s'}</span></div>${contactLogTable(newestContactEventsFirst(filtered))}</section>`;}
function openLogDetail(eventId){const e=state.events.find(event=>event.id===eventId);const s=e&&eventStudent(e);const openFollowUp=e&&state.followUps.find(followUp=>followUp.contactEventId===e.id||followUp.id===e.followUpId);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal log-detail-modal"><div class="modal-header"><div><p class="eyebrow">Contact record</p><h2>${s?.name||'Student'} · ${s?.relation||'Parent'}</h2><p>${e?.time||'—'}</p></div><button class="close" data-close>×</button></div><div class="log-detail-grid"><div><span>Outcome</span><strong><span class="status ${statusClass(e?.result||'Failed')}">${e?.result||'—'}</span></strong></div><div><span>Duration</span><strong>${e?.duration||'—'}</strong></div><div><span>Topic</span><strong>${escapeHtml(e?.topic||'—')}</strong></div><div><span>Attempt</span><strong>#${e?.attemptNumber||'—'}</strong></div></div><div class="log-detail-copy"><p><b>Teacher-approved note</b><br>${escapeHtml(e?.note||'No teacher-approved note recorded.')}</p><p><b>Follow-up</b><br>${openFollowUp?'Open · '+followUpLabel(openFollowUp.dueAt||openFollowUp.due_at):'None'}</p></div><div class="modal-footer"><button class="button-primary" data-close>Done</button></div></div></div>`;document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML=''});}
function exportFilteredContactLog(){const filtered=filterContactLogEvents(state.events,state.logFilters,state.students);const csv=toContactLogCsv(newestContactEventsFirst(filtered),state.students);const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='contactloop-contact-records.csv';link.click();URL.revokeObjectURL(url);}
function renderMeetingBriefSettings(){const settings=state.meetingSettings;const custom=settings.range.preset==='custom';document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal meeting-settings-modal"><div class="modal-header"><div><p class="eyebrow">Meeting materials</p><h2>Generate Meeting Brief</h2><p>Build a print-friendly summary from teacher-confirmed records.</p></div><button class="close" data-meeting-cancel>×</button></div><div class="form-grid"><label>Student<select id="meeting-student">${state.students.map(s=>`<option value="${s.id}" ${settings.studentId===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label>Date range<select id="meeting-range"><option value="today" ${settings.range.preset==='today'?'selected':''}>Today</option><option value="this-week" ${settings.range.preset==='this-week'?'selected':''}>This Week</option><option value="this-month" ${settings.range.preset==='this-month'?'selected':''}>This Month</option><option value="this-year" ${settings.range.preset==='this-year'?'selected':''}>This Year</option><option value="custom" ${custom?'selected':''}>Custom</option></select></label>${custom?`<label>From<input id="meeting-from" type="date" value="${settings.range.from}"></label><label>To<input id="meeting-to" type="date" value="${settings.range.to}"></label>`:''}</div><div class="meeting-options"><label><input type="checkbox" id="meeting-history" ${settings.includeHistory?'checked':''}> Include detailed contact history</label><label><input type="checkbox" id="meeting-notes" ${settings.includeNotes?'checked':''}> Include teacher-approved notes</label><label class="disabled-option"><input type="checkbox" disabled ${settings.includeAI?'checked':''}> Include AI summary <small>Not connected in this MVP</small></label><label><input type="checkbox" id="meeting-hide-phone" ${settings.hidePhone?'checked':''}> Hide parent phone numbers</label></div><div class="modal-footer"><button class="button-cancel" data-meeting-cancel>Cancel</button><button class="button-primary" data-meeting-generate>Generate brief</button></div></div></div>`;document.querySelectorAll('[data-meeting-cancel]').forEach(button=>button.onclick=()=>{state.meetingSettings=null;document.querySelector('#modal-root').innerHTML=''});const studentInput=document.querySelector('#meeting-student');if(studentInput)studentInput.onchange=()=>{settings.studentId=studentInput.value};const rangeInput=document.querySelector('#meeting-range');if(rangeInput)rangeInput.onchange=()=>{settings.range={preset:rangeInput.value,from:'',to:''};renderMeetingBriefSettings()};const fromInput=document.querySelector('#meeting-from');if(fromInput)fromInput.onchange=()=>{settings.range.from=fromInput.value};const toInput=document.querySelector('#meeting-to');if(toInput)toInput.onchange=()=>{settings.range.to=toInput.value};document.querySelector('#meeting-history')?.addEventListener('change',event=>{settings.includeHistory=event.target.checked});document.querySelector('#meeting-notes')?.addEventListener('change',event=>{settings.includeNotes=event.target.checked});document.querySelector('#meeting-hide-phone')?.addEventListener('change',event=>{settings.hidePhone=event.target.checked});document.querySelector('[data-meeting-generate]')?.addEventListener('click',generateMeetingBrief);}
function openMeetingBriefSettings(){state.meetingSettings={studentId:state.logFilters.studentId!=='all'?state.logFilters.studentId:(state.students[0]?.id||''),range:{...state.logFilters.range},includeHistory:true,includeNotes:true,includeAI:false,hidePhone:true};renderMeetingBriefSettings();}
function generateMeetingBrief(){const settings=state.meetingSettings;state.meetingBrief=buildMeetingBrief({events:state.events,students:state.students,followUps:state.followUps,studentId:settings.studentId,range:settings.range,teacherName:'Bella Rivera'});state.meetingBrief.settings={...settings};state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='meeting-brief';render();}
function meetingBriefScreen(){const brief=state.meetingBrief;const settings=brief.settings;const s=brief.student;const topics=brief.topics.length?brief.topics.map(topic=>`<span class="brief-topic">${escapeHtml(topic.label)} <b>${topic.count}</b></span>`).join(''):'<span class="brief-muted">No topics recorded.</span>';const notes=items=>settings.includeNotes?items.map(item=>`<li>${escapeHtml(item)}</li>`).join(''):'<li>Teacher-approved notes were not included.</li>';return `<div class="meeting-brief-toolbar"><button class="back" data-nav="log">← Back to Contact Log</button><div><button class="button-secondary" data-action="print-brief">Print</button></div></div><article class="meeting-brief-document"><header class="brief-header"><div><p class="eyebrow">ContactLoop · Meeting Brief</p><h1>${escapeHtml(s?.name||'Student')}</h1><p>Parent communication summary</p></div><div class="brief-meta"><span>Reporting period</span><strong>${escapeHtml(brief.reportingPeriod)}</strong><span>Generated</span><strong>${escapeHtml(brief.generatedDate)}</strong></div></header><section class="brief-section student-information"><h2>Student Information</h2><div class="brief-info-grid"><div><span>Student</span><strong>${escapeHtml(s?.name||'—')}</strong></div><div><span>Teacher</span><strong>${escapeHtml(brief.teacherName)}</strong></div><div><span>Parent / guardian</span><strong>${escapeHtml(`${s?.relation||'Parent'} · ${s?.parent||'—'}`)}</strong></div><div><span>Phone</span><strong>${settings.hidePhone?'Hidden':escapeHtml(s?.phone||'—')}</strong></div></div></section><section class="brief-section"><h2>Communication Overview</h2><div class="overview-grid"><div><strong>${brief.overview.totalAttempts}</strong><span>Contact attempts</span></div><div><strong>${brief.overview.successfulConversations}</strong><span>Successful conversations</span></div><div><strong>${brief.overview.noAnswer}</strong><span>No answers</span></div><div><strong>${brief.overview.busy}</strong><span>Busy</span></div><div><strong>${brief.overview.failed}</strong><span>Failed</span></div><div><strong>${brief.overview.openFollowUps}</strong><span>Open follow-ups</span></div></div><p class="brief-callout">Last successful contact: <b>${escapeHtml(brief.overview.lastSuccessfulContact)}</b></p></section><section class="brief-columns"><section class="brief-section"><h2>Key Topics Discussed</h2><div class="brief-topic-list">${topics}</div></section><section class="brief-section"><h2>Optional Contact Insights</h2><ul>${brief.insights.length?brief.insights.map(item=>`<li>${escapeHtml(item)}</li>`).join(''):'<li>No additional pattern recorded.</li>'}</ul></section></section><section class="brief-columns"><section class="brief-section"><h2>Parent Concerns / Requests</h2><ul>${notes(brief.concerns)}</ul></section><section class="brief-section"><h2>Agreements / Commitments</h2><ul>${notes(brief.agreements)}</ul></section></section><section class="brief-section"><h2>Open Follow-ups</h2>${brief.openFollowUps.length?`<div class="brief-followups">${brief.openFollowUps.map(followUp=>`<div><strong>${escapeHtml(followUp.title||followUp.description||'Follow-up task')}</strong><span>Due ${escapeHtml(formatEventTime(followUp.dueAt||followUp.due_at))} · Open</span></div>`).join('')}</div>`:'<p class="brief-muted">No open follow-ups.</p>'}</section>${settings.includeHistory?`<div class="brief-page-break"></div><section class="brief-section detailed-history"><h2>Detailed Contact History</h2><table><thead><tr><th>Date / Time</th><th>Parent / Guardian</th><th>Method</th><th>Outcome</th><th>Duration</th><th>Topic</th><th>Teacher-approved note</th><th>Follow-up status</th></tr></thead><tbody>${brief.detailedHistory.map(event=>`<tr><td>${escapeHtml(event.displayTime)}</td><td>${escapeHtml(s?.relation||'Parent')}</td><td>Phone</td><td>${escapeHtml(event.result)}</td><td>${escapeHtml(event.duration||'—')}</td><td>${escapeHtml(event.topic||'—')}</td><td>${escapeHtml(settings.includeNotes?(event.note||'—'):'Not included')}</td><td>${escapeHtml(event.followUpStatus)}</td></tr>`).join('')}</tbody></table></section>`:''}</article>`;}
function authScreen(){const isSignUp=state.auth.mode==='sign-up';return `<section class="auth-card"><div class="auth-brand"><span class="brand-mark">C</span><span>Contact<span>Loop</span></span></div><p class="eyebrow">${isSignUp?'Create your workspace':'Welcome back'}</p><h1>${isSignUp?'Start your contact loop.':'Sign in to ContactLoop.'}</h1><p class="auth-copy">${isSignUp?'Create an account to keep your students and guardian contacts private.':'Access your private student and guardian workspace.'}</p>${state.auth.error?`<div class="auth-error">${escapeHtml(state.auth.error)}</div>`:''}${state.auth.message?`<div class="auth-message">${escapeHtml(state.auth.message)}</div>`:''}${state.auth.status==='loading'?'<div class="auth-loading">Checking your session…</div>':`<form class="auth-form" data-auth-form><label>Email<input id="auth-email" type="email" autocomplete="email" value="${escapeHtml(state.auth.email)}" placeholder="teacher@example.com" required></label><label>Password<input id="auth-password" type="password" autocomplete="${isSignUp?'new-password':'current-password'}" value="${escapeHtml(state.auth.password)}" placeholder="At least 6 characters" required></label><button class="button-primary" type="submit">${isSignUp?'Create account':'Sign in'}</button></form><button class="auth-toggle" data-auth-mode>${isSignUp?'Already have an account? Sign in':'New to ContactLoop? Create an account'}</button>`}</section>`;}
function dataStatusScreen(){ const setup=state.error==='setup'; return `<section class="data-status panel"><div class="status-orb">${setup?'↗':'!'}</div><p class="eyebrow">${setup?'Supabase connection required':'Could not load workspace data'}</p><h1>${setup?'Connect ContactLoop to Supabase':'Your workspace needs attention'}</h1><p>${setup?'Add VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY to .env.local, then run the schema in supabase/schema.sql. The app will use Supabase data only.':escapeHtml(state.error)}</p><button class="button-primary" data-action="retry-data">Retry connection</button></section>`; }
function screenContent(){ if(state.screen==='home')return homeScreen();if(AUTH_REQUIRED&&state.auth.status!=='authenticated')return authScreen();if(state.loading)return '<section class="data-status panel"><div class="status-orb">↻</div><p class="eyebrow">Loading workspace</p><h1>Getting your contact data.</h1><p>ContactLoop is fetching students, contact history, and follow-ups from Supabase.</p></section>';if(state.error)return dataStatusScreen();if(state.screen==='dashboard')return dashboard();if(state.screen==='students')return studentsScreen();if(state.screen==='import-students')return renderImportScreen(state.importState);if(state.screen==='followups')return followupsScreen();if(state.screen==='log')return logScreen();if(state.screen==='meeting-brief')return meetingBriefScreen();if(state.screen==='detail')return detailScreen(state.selectedStudentId);return dashboard(); }
function render(){const authGate=AUTH_REQUIRED&&state.screen!=='home'&&state.auth.status!=='authenticated';document.querySelector('#app').innerHTML=authGate?`<div class="auth-shell">${screenContent()}</div>`:state.screen==='home'?screenContent():`<div class="app-shell"><aside class="sidebar"><button class="brand" data-home><div class="brand-mark">C</div><div class="brand-copy">Contact<span>Loop</span></div></button><div class="nav-label">Workspace</div><nav class="nav">${renderNav()}</nav><div class="sidebar-foot"><strong>Every contact, automatically tracked.</strong>Let teachers focus on the conversation.</div></aside><main class="main">${screenContent()}</main></div>`; bindEvents(); }

function openCallFlow(id){state.selectedStudentId=id;state.modal={step:'planned-topic',plannedTopic:null,result:null,discussedTopics:[],followUp:'Tomorrow',note:''};renderModal();}
function renderPlannedTopicModal(){const m=state.modal;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal planned-topic-modal"><div class="modal-header"><div><p class="eyebrow">Before you call</p><h2>What’s this call about?</h2><p>Choose a reason so ContactLoop can keep the outreach context clear.</p></div><button class="close" data-close>×</button></div><div class="topic-grid">${CALL_TOPICS.map(topic=>`<button class="topic ${m.plannedTopic===topic?'selected':''}" data-planned-topic="${topic}">${topic}</button>`).join('')}</div><div class="modal-footer"><button class="button-cancel" data-close>Cancel</button><button class="button-primary" data-call-now>Call now</button></div></div></div>`;document.querySelectorAll('[data-planned-topic]').forEach(button=>button.onclick=()=>{state.modal.plannedTopic=button.dataset.plannedTopic;renderModal()});document.querySelector('[data-call-now]')?.addEventListener('click',()=>{const plannedTopic=state.modal.plannedTopic;state.pendingPlannedTopic=plannedTopic||null;if(TELEPHONY_PROVIDER==='twilio'){state.modal=null;document.querySelector('#modal-root').innerHTML='';startRealCall(state.selectedStudentId,plannedTopic||null);}else{state.modal={step:'outcome',result:null,plannedTopic:plannedTopic||null,discussedTopics:plannedTopic?[plannedTopic]:[],followUp:'Tomorrow',note:''};renderModal()}});}
function renderModal(){const m=state.modal;if(m.step==='planned-topic'){renderPlannedTopicModal();return;}if(m.step==='voice'){document.querySelector('#modal-root').innerHTML=renderVoiceModal();bindVoiceModalEvents();return;}if(m.step==='teacher-note'){document.querySelector('#modal-root').innerHTML=renderTeacherNoteModal();bindTeacherNoteModalEvents();return;}if(m.step==='add-student'){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-header"><div><h2>Add a student</h2><p>Save a student and their primary guardian to Supabase.</p></div><button class="close" data-close>×</button></div><div class="form-grid"><label>Student name<input id="student-name" value="${escapeHtml(m.name)}" placeholder="e.g. Jordan Lee"></label><label>Parent / guardian name<input id="guardian-name" value="${escapeHtml(m.guardianName)}" placeholder="e.g. Taylor Lee"></label><label>Relationship<select id="guardian-relation"><option ${m.relation==='Mom'?'selected':''}>Mom</option><option ${m.relation==='Dad'?'selected':''}>Dad</option><option ${m.relation==='Guardian'?'selected':''}>Guardian</option><option ${m.relation==='Other'?'selected':''}>Other</option></select></label><label>Phone number<input id="guardian-phone" value="${escapeHtml(m.phone)}" placeholder="(415) 555-0199"></label></div><div class="modal-footer"><button class="button-cancel" data-close>Cancel</button><button class="button-primary" data-save-student ${!m.name.trim()||!m.guardianName.trim()||!m.phone.trim()?'disabled':''}>Add student</button></div></div></div>`;bindModalEvents();return;}if(m.step==='pick'){const query=(m.search||'').trim().toLowerCase();const matches=state.students.filter(s=>`${s.name} ${s.parent} ${s.phone}`.toLowerCase().includes(query));document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-header"><div><h2>Who are you calling?</h2><p>Choose a student to start a parent contact.</p></div><button class="close" data-close>×</button></div><div class="picker-search"><span>⌕</span><input id="student-search" value="${escapeHtml(m.search||'')}" placeholder="Search students or parents…"></div><div class="picker-list">${matches.map(s=>`<button class="picker-row" data-pick-student="${s.id}">${avatar(s)}<span><strong>${s.name}</strong><small>${s.relation} · ${s.parent}</small></span><b>→</b></button>`).join('')||'<div class="empty-state">No students match that search.</div>'}</div><div class="modal-footer"><button class="button-cancel" data-close>Cancel</button></div></div></div>`;bindModalEvents();return;}const s=student(state.selectedStudentId);let body='';if(m.step==='outcome')body=`<div class="modal-label">What happened?</div><div class="outcome-grid">${[['Connected','7m 43s · conversation complete'],['No Answer','Rings out'],['Busy','Line was busy'],['Failed','Could not connect']].map(([r,d])=>`<button class="outcome ${m.result===r?'selected':''}" data-outcome="${r}">${r}<span>${d}</span></button>`).join('')}</div>`;if(m.step==='details')body=`<p class="planned-topic-note">Planned topic: <strong>${m.plannedTopic||"Not specified"}</strong></p><div class="modal-label">What did you discuss?</div><div class="topic-grid">${CALL_TOPICS.map(t=>`<button class="topic ${m.discussedTopics?.includes(t)?'selected':''}" data-topic="${t}">${t}</button>`).join('')}</div><label class="modal-label" for="note">Optional note <span style="text-transform:none;letter-spacing:0">· teacher confirmed</span></label><textarea id="note" placeholder="e.g. Dad confirmed Friday at 2 and asked about transportation.">${escapeHtml(m.note)}</textarea>`;if(m.step==='followup')body=`<div class="modal-label">When should we try again?</div><div class="followup-options">${['Tomorrow','In 2 days','In 3 days','Next week'].map(t=>`<button class="followup-option ${m.followUp===t?'selected':''}" data-followup="${t}">${t}</button>`).join('')}</div>`;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-header"><div><h2>${m.step==='outcome'?'Start a contact':m.step==='details'?'Nice conversation.':'Keep the loop closed.'}</h2><p>${m.step==='outcome'?`Calling ${s.parent}, ${s.relation.toLowerCase()} of ${s.name}`:m.step==='details'?'One tap to keep the record useful.':'We’ll bring this back to your attention when it’s due.'}</p></div><button class="close" data-close>×</button></div><div class="call-preview">${avatar(s)}<div><strong>${s.name}</strong><span>${s.relation} · ${s.phone}</span></div></div>${body}<div class="modal-footer"><button class="button-cancel" data-close>Cancel</button><button class="button-primary" ${m.step==='outcome'&&!m.result?'disabled':''} data-modal-next>${m.step==='outcome'?(m.result==='Connected'?'Continue':'Schedule follow-up'):m.step==='details'?'Save note':'Save contact'}</button></div></div></div>`;bindModalEvents();}
function followUpDueAt(label){ const days=label==='Tomorrow'?1:label==='In 2 days'?2:label==='In 3 days'?3:7; const due=new Date(); due.setDate(due.getDate()+days); due.setHours(9,0,0,0); return due.toISOString(); }
async function completeCall(){const s=student(state.selectedStudentId),m=state.modal;try{await createContactEvent({studentId:s.id,guardianId:s.guardianId,result:m.result,durationSeconds:m.result==='Connected'?463:null,plannedTopic:m.plannedTopic,discussedTopics:normalizeDiscussedTopics(m.result,m.plannedTopic,m.discussedTopics),topic:m.result==='Connected'?topicLabel(m.plannedTopic,m.discussedTopics,m.result):m.plannedTopic,teacherNote:m.note,followUpDueAt:m.result==='Connected'?null:followUpDueAt(m.followUp)});state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='detail';await refreshData();}catch(error){state.modal=null;document.querySelector('#modal-root').innerHTML='';state.error=error.message||'Unable to save this contact event.';render();}}
function bindVoiceModalEvents(){document.querySelectorAll('[data-voice-cancel]').forEach(button=>button.onclick=closeVoiceNote);document.querySelector('[data-voice-start]')?.addEventListener('click',startVoiceRecording);document.querySelector('[data-voice-stop]')?.addEventListener('click',stopVoiceRecording);document.querySelector('[data-voice-retry]')?.addEventListener('click',()=>{state.voiceNote=createVoiceNoteState();renderModal()});document.querySelector('[data-voice-save]')?.addEventListener('click',saveVoiceNote);document.querySelector('#voice-transcript')?.addEventListener('input',event=>{state.voiceNote.transcript=event.target.value;});}
function bindModalEvents(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML=''});document.querySelectorAll('[data-pick-student]').forEach(b=>b.onclick=()=>openCallFlow(b.dataset.pickStudent));document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>{state.modal.result=b.dataset.outcome;renderModal()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{const topic=b.dataset.topic;const topics=state.modal.discussedTopics||[];state.modal.discussedTopics=topics.includes(topic)?topics.filter(item=>item!==topic):[...topics,topic];renderModal()});document.querySelectorAll('[data-followup]').forEach(b=>b.onclick=()=>{state.modal.followUp=b.dataset.followup;renderModal()});const search=document.querySelector('#student-search');if(search)search.oninput=()=>{state.modal.search=search.value;renderModal();document.querySelector('#student-search')?.focus();};const studentName=document.querySelector('#student-name');if(studentName)studentName.oninput=()=>{state.modal.name=studentName.value;renderModal();document.querySelector('#student-name')?.focus();};const guardianName=document.querySelector('#guardian-name');if(guardianName)guardianName.oninput=()=>{state.modal.guardianName=guardianName.value;renderModal();document.querySelector('#guardian-name')?.focus();};const relation=document.querySelector('#guardian-relation');if(relation)relation.onchange=()=>{state.modal.relation=relation.value;renderModal()};const phone=document.querySelector('#guardian-phone');if(phone)phone.oninput=()=>{state.modal.phone=phone.value;renderModal();document.querySelector('#guardian-phone')?.focus();};document.querySelector('[data-save-student]')?.addEventListener('click',saveNewStudent);const note=document.querySelector('#note');if(note)note.oninput=()=>state.modal.note=note.value;const next=document.querySelector('[data-modal-next]');if(next)next.onclick=()=>{if(state.modal.step==='outcome'){state.modal.step=state.modal.result==='Connected'?'details':'followup';renderModal()}else completeCall()};}
function openParentPicker(){state.modal={step:'pick',search:''};renderModal();}
function openAddStudent(){state.modal={step:'add-student',name:'',guardianName:'',relation:'Mom',phone:''};renderModal();}
async function saveNewStudent(){const m=state.modal;if(!m.name.trim()||!m.guardianName.trim()||!m.phone.trim())return;try{await createStudent({name:m.name.trim(),guardianName:m.guardianName.trim(),relation:m.relation,phone:m.phone.trim()});state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='students';await refreshData();}catch(error){state.error=error.message||'Unable to add this student.';state.modal=null;document.querySelector('#modal-root').innerHTML='';render();}}
async function markFollowUpDone(id){try{await updateFollowUp(id,{status:'completed'});await refreshData();}catch(error){state.error=error.message||'Unable to complete this follow-up.';render();}}
async function rescheduleFollowUp(id){const value=window.prompt('Enter a new date (YYYY-MM-DD):');if(!value)return;const due=new Date(`${value}T09:00:00`);if(Number.isNaN(due.getTime())){window.alert('Please use YYYY-MM-DD.');return;}try{await updateFollowUp(id,{due_at:due.toISOString(),status:'open'});await refreshData();}catch(error){state.error=error.message||'Unable to reschedule this follow-up.';render();}}
function openImportStudents(){state.screen='import-students';state.importState={step:'upload',fileName:'',headers:[],rawRows:[],mapping:{},rows:[],stats:null,result:null,error:null};render();}
async function handleImportFile(file){if(!file)return;const extension=file.name.toLowerCase().split('.').pop();if(!['csv','xlsx'].includes(extension)){state.importState={...state.importState,error:'Please choose a CSV or XLSX file.'};render();return;}try{const parsed=extension==='csv'?parseCsvText(await file.text()):parseWorkbook(await file.arrayBuffer());if(!parsed.headers.length)throw new Error('This file does not contain a header row.');state.importState={...state.importState,fileName:file.name,headers:parsed.headers,rawRows:parsed.rows,mapping:suggestColumnMapping(parsed.headers),error:null,step:'mapping'};render();}catch(error){state.importState={...state.importState,error:error.message||'Unable to parse this file.'};render();}}
function continueImportMapping(){const mapping=state.importState.mapping;if(!Object.values(mapping).some(value=>value==='student_full_name'||value==='student_first_name')||!Object.values(mapping).includes('guardian_name')){state.importState={...state.importState,error:'Map a student name and guardian name before continuing.'};render();return;}const rows=normalizeImportRows(state.importState.rawRows,mapping);const validation=validateImportRows(rows,state.students);state.importState={...state.importState,...validation,step:'review',error:null};render();}
function editImportRow(index,field,value){const rows=state.importState.rows.map((row,rowIndex)=>{if(rowIndex!==index)return row;const next={...row,student:{...row.student},guardian:{...row.guardian}};if(field==='student'){next.student.name=value;const parts=value.trim().split(/\s+/);next.student.firstName=parts.slice(0,-1).join(' ');next.student.lastName=parts.at(-1)||'';next.studentKey=value.trim().toLowerCase().replace(/\s+/g,' ');}else next.guardian[field]=value;return next;});const validation=validateImportRows(rows,state.students);state.importState={...state.importState,...validation};render();}
async function submitImport(){const chosen=state.importState.rows.filter(row=>row.status==='ready'||(row.status==='duplicate'&&row.action!=='skip'));if(!chosen.length)return;state.importState={...state.importState,error:null,loading:true};render();try{const result=await importStudents(buildImportPayload(chosen));state.importState={...state.importState,result,loading:false,step:'complete',rows:[],rawRows:[]};state.screen='import-students';await refreshData();}catch(error){state.importState={...state.importState,loading:false,error:error.message||'Unable to import students.'};render();}}
async function handleAuthSubmit(event){event.preventDefault();const email=document.querySelector('#auth-email')?.value.trim()||'';const password=document.querySelector('#auth-password')?.value||'';state.auth={...state.auth,email,password,status:'loading',error:null,message:null};render();try{const result=state.auth.mode==='sign-up'?await signUpWithPassword(email,password):await signInWithPassword(email,password);if(result.error)throw result.error;if(state.auth.mode==='sign-up'&&!result.data?.session){state.auth={...state.auth,status:'signed-out',password:'',message:'Check your email to confirm your account.'};render();return;}state.auth={...state.auth,status:'authenticated',password:'',error:null,message:null};state.loading=true;render();await refreshData();}catch(error){state.auth={...state.auth,status:'signed-out',password:'',error:error.message||'Unable to authenticate.',message:null};render();}}
async function initializeAuth(){try{const session=await getAuthSession();state.auth={...state.auth,status:session?'authenticated':'signed-out',session,error:null};render();if(session)await refreshData();}catch(error){state.auth={...state.auth,status:'signed-out',error:error.message||'Unable to check your session.'};render();}subscribeToAuthChanges((_event,session)=>{state.auth={...state.auth,status:session?'authenticated':'signed-out',session,error:null};if(session){state.loading=true;refreshData();}else{state.students=[];state.events=[];state.followUps=[];state.loading=false;}render();});}
function bindEvents(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.screen=b.dataset.nav;render()});document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{state.screen='home';render()});document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{state.screen='detail';state.selectedStudentId=b.dataset.student;render()});document.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>handleCallClick(b.dataset.call));document.querySelectorAll('[data-ai-generate]').forEach(b=>b.onclick=()=>generateAiContactSummary(b.dataset.aiGenerate));document.querySelectorAll('[data-ai-edit]').forEach(b=>b.onclick=()=>beginAiSummaryEdit(b.dataset.aiEdit));document.querySelectorAll('[data-ai-cancel]').forEach(b=>b.onclick=()=>cancelAiSummaryEdit(b.dataset.aiCancel));document.querySelectorAll('[data-ai-save]').forEach(b=>b.onclick=()=>saveAiSummaryEdits(b.dataset.aiSave));document.querySelectorAll('[data-ai-approve]').forEach(b=>b.onclick=()=>approveAiSummary(b.dataset.aiApprove));document.querySelectorAll('[data-ai-remove]').forEach(b=>b.onclick=()=>removeAiSummary(b.dataset.aiRemove));document.querySelectorAll('[data-ai-regenerate]').forEach(b=>b.onclick=()=>generateAiContactSummary(b.dataset.aiRegenerate));document.querySelectorAll('[data-ai-menu-toggle]').forEach(b=>b.onclick=event=>{event.stopPropagation();document.querySelector(`[data-ai-menu="${b.dataset.aiMenuToggle}"]`)?.classList.toggle('open')});document.querySelectorAll('[data-ai-item]').forEach(input=>input.oninput=()=>{const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor)result.editor=updateBriefItem(result.editor,input.dataset.aiItem,Number(input.dataset.aiIndex),input.value)});document.querySelectorAll('[data-ai-delete]').forEach(b=>b.onclick=()=>{const [field,index]=b.dataset.aiDelete.split(':');const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor){result.editor=deleteBriefItem(result.editor,field,Number(index));render()}});document.querySelectorAll('[data-ai-add]').forEach(b=>b.onclick=()=>{const value=window.prompt(`Add ${b.dataset.aiAdd.replace(/s$/,'')}`);if(!value)return;const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor){result.editor=addBriefItem(result.editor,b.dataset.aiAdd,value);render()}});document.querySelector('[data-ai-next-step]')?.addEventListener('input',event=>{const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor)result.editor.brief.suggested_next_step=event.target.value});document.querySelectorAll('[data-log-event]').forEach(row=>{row.onclick=()=>openLogDetail(row.dataset.logEvent);row.onkeydown=event=>{if(event.key==='Enter'||event.key===' ')openLogDetail(row.dataset.logEvent)}});document.querySelectorAll('[data-action="demo"]').forEach(b=>b.onclick=()=>{state.screen='dashboard';render()});document.querySelector('[data-action="try-emma"]')?.addEventListener('click',()=>{const emma=state.students.find(s=>s.name==='Emma Johnson');if(!emma)return;state.screen='detail';state.selectedStudentId=emma.id;render();handleCallClick(emma.id)});document.querySelector('[data-action="call-parent"]')?.addEventListener('click',openParentPicker);document.querySelector('[data-action="retry-data"]')?.addEventListener('click',refreshData);document.querySelector('[data-action="new-student"]')?.addEventListener('click',openAddStudent);document.querySelector('[data-action="export"]')?.addEventListener('click',()=>alert('CSV export is ready for the next MVP phase.'));
  document.querySelectorAll('[data-followup-menu-toggle]').forEach(button=>button.onclick=event=>{event.stopPropagation();const menu=document.querySelector(`[data-followup-menu="${button.dataset.followupMenuToggle}"]`);document.querySelectorAll('.followup-menu.open').forEach(openMenu=>{if(openMenu!==menu)openMenu.classList.remove('open')});menu?.classList.toggle('open')});
  document.querySelectorAll('[data-followup-done]').forEach(button=>button.onclick=()=>markFollowUpDone(button.dataset.followupDone));
  document.querySelectorAll('[data-followup-reschedule]').forEach(button=>button.onclick=()=>rescheduleFollowUp(button.dataset.followupReschedule));
  document.querySelectorAll('[data-followup-history]').forEach(button=>button.onclick=()=>{state.screen='detail';state.selectedStudentId=button.dataset.followupHistory;render()});
  const rangeSelect=document.querySelector('#dashboard-range');if(rangeSelect)rangeSelect.onchange=()=>{state.dashboardRange={...state.dashboardRange,preset:rangeSelect.value};if(rangeSelect.value!=='custom')state.dashboardRange={preset:rangeSelect.value,from:'',to:''};render()};
  const fromInput=document.querySelector('#dashboard-from');if(fromInput)fromInput.onchange=()=>{state.dashboardRange={...state.dashboardRange,from:fromInput.value};render()};
  const toInput=document.querySelector('#dashboard-to');if(toInput)toInput.onchange=()=>{state.dashboardRange={...state.dashboardRange,to:toInput.value};render()};
  const studentSearchInput=document.querySelector('#student-page-search');if(studentSearchInput)studentSearchInput.oninput=()=>{const value=studentSearchInput.value;const cursor=studentSearchInput.selectionStart??value.length;state.studentSearch=value;render();const next=document.querySelector('#student-page-search');if(next){next.focus();next.setSelectionRange(cursor,cursor)}};
  const logSearch=document.querySelector('#log-search');if(logSearch)logSearch.oninput=()=>{const value=logSearch.value;const cursor=logSearch.selectionStart??value.length;state.logFilters={...state.logFilters,search:value};render();const next=document.querySelector('#log-search');if(next){next.focus();next.setSelectionRange(cursor,cursor)}};
  const logRange=document.querySelector('#log-range');if(logRange)logRange.onchange=()=>{state.logFilters={...state.logFilters,range:{preset:logRange.value,from:'',to:''}};render()};
  const logOutcome=document.querySelector('#log-outcome');if(logOutcome)logOutcome.onchange=()=>{state.logFilters={...state.logFilters,outcome:logOutcome.value};render()};
  const logStudent=document.querySelector('#log-student');if(logStudent)logStudent.onchange=()=>{state.logFilters={...state.logFilters,studentId:logStudent.value};render()};
  const logFrom=document.querySelector('#log-from');if(logFrom)logFrom.onchange=()=>{state.logFilters={...state.logFilters,range:{...state.logFilters.range,from:logFrom.value}};render()};
  const logTo=document.querySelector('#log-to');if(logTo)logTo.onchange=()=>{state.logFilters={...state.logFilters,range:{...state.logFilters.range,to:logTo.value}};render()};
  document.querySelector('[data-action="export-log"]')?.addEventListener('click',exportFilteredContactLog);
  document.querySelector('[data-action="meeting-brief"]')?.addEventListener('click',openMeetingBriefSettings);
  document.querySelector('[data-action="print-brief"]')?.addEventListener('click',()=>window.print());
}
const modalObserver=new MutationObserver(()=>{const skip=document.querySelector('.modal:has(#note) .modal-footer .button-cancel');if(skip&&!skip.dataset.noteSkip){skip.dataset.noteSkip='true';skip.removeAttribute('data-close');skip.onclick=()=>completeCall();}const search=document.querySelector('#student-search');if(search&&!search.dataset.nativeSearch){search.dataset.nativeSearch='true';search.oninput=()=>{const query=search.value.trim().toLowerCase();state.modal.search=search.value;document.querySelectorAll('.picker-row').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(query);});};}const fields=[['student-name','name'],['guardian-name','guardianName'],['guardian-phone','phone']];fields.forEach(([id,key])=>{const field=document.querySelector(`#${id}`);if(field&&!field.dataset.nativeInput){field.dataset.nativeInput='true';field.oninput=()=>{state.modal[key]=field.value;const save=document.querySelector('[data-save-student]');if(save)save.disabled=!state.modal.name.trim()||!state.modal.guardianName.trim()||!state.modal.phone.trim();};}});const relation=document.querySelector('#guardian-relation');if(relation&&!relation.dataset.nativeInput){relation.dataset.nativeInput='true';relation.onchange=()=>{state.modal.relation=relation.value;};}});modalObserver.observe(document.querySelector('#modal-root'),{childList:true,subtree:true});
render();
document.addEventListener('submit',event=>{if(event.target.matches('[data-auth-form]'))handleAuthSubmit(event);});
document.addEventListener('click',event=>{if(event.target.closest?.('[data-auth-mode]')){state.auth={...state.auth,mode:state.auth.mode==='sign-up'?'sign-in':'sign-up',error:null,message:null};render();}});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-ai-voice]');if(button)openVoiceNote(button.dataset.aiVoice);});
document.addEventListener('click',event=>{
  const importButton=event.target.closest?.('[data-action="import-students"]');
  if(importButton){openImportStudents();return;}
  const back=event.target.closest?.('[data-import-back]');
  if(back){
    if(state.importState?.step==='mapping')state.importState={...state.importState,step:'upload',error:null};
    else if(state.importState?.step==='review')state.importState={...state.importState,step:'mapping',error:null};
    else {state.screen='students';state.importState=null;}
    render();
    return;
  }
  if(event.target.closest?.('[data-import-continue]')){continueImportMapping();return;}
  if(event.target.closest?.('[data-import-submit]')){submitImport();return;}
  if(event.target.closest?.('[data-download-template]')){downloadContactLoopTemplate();return;}
  if(event.target.closest?.('[data-view-students]')){state.screen='students';state.importState=null;render();}
});
document.addEventListener('change',event=>{
  if(event.target.matches?.('#import-file')){handleImportFile(event.target.files?.[0]);return;}
  if(event.target.matches?.('[data-import-mapping]')){state.importState={...state.importState,mapping:{...state.importState.mapping,[event.target.dataset.importMapping]:event.target.value},error:null};render();return;}
  if(event.target.matches?.('[data-import-action]')){const index=Number(event.target.dataset.importAction);const rows=state.importState.rows.map((row,rowIndex)=>rowIndex===index?{...row,action:event.target.value}:row);state.importState={...state.importState,rows,stats:{...state.importState.stats}};render();return;}
  if(event.target.matches?.('[data-import-edit]')){const [index,field]=event.target.dataset.importEdit.split(':');editImportRow(Number(index),field,event.target.value);}
});
document.addEventListener('dragover',event=>{if(event.target.closest?.('.import-dropzone'))event.preventDefault();});
document.addEventListener('drop',event=>{const zone=event.target.closest?.('.import-dropzone');if(!zone)return;event.preventDefault();handleImportFile(event.dataTransfer?.files?.[0]);});
if(AUTH_REQUIRED)initializeAuth();else refreshData().then(()=>{if(TELEPHONY_PROVIDER==='twilio')syncCallAndRefresh();});
